/**
 * @name Unsafe deserialization with user input
 * @description User-controlled data flowing to unsafe deserialization operations
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization-taint
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module UnsafeDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for pickle.loads calls
    exists(API::CallNode call |
      call = API::moduleImport("pickle").getMember(["loads", "load", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Check for marshal.loads calls
    exists(API::CallNode call |
      call = API::moduleImport("marshal").getMember(["loads", "load"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Check for yaml.load calls
    exists(API::CallNode call |
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UnsafeDeserializationFlow = TaintTracking::Global<UnsafeDeserializationConfig>;
import UnsafeDeserializationFlow::PathGraph

from UnsafeDeserializationFlow::PathNode source, UnsafeDeserializationFlow::PathNode sink
where UnsafeDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization from $@.", source.getNode(), "user input"
